function infixToPrefix(s) {
  function prec(c) {
    if (c === '^') return 3;
    if (c === '*' || c === '/') return 2;
    if (c === '+' || c === '-') return 1;
    return -1;
  }
  let rev = "";
  for (let i = s.length - 1; i >= 0; i--) {
    if (s[i] === '(') rev += ')';
    else if (s[i] === ')') rev += '(';
    else rev += s[i];
  }
  const st = [];
  let post = "";
  for (let i = 0; i < rev.length; i++) {
    const c = rev[i];
    if (/[a-zA-Z0-9]/.test(c)) {
      post += c;
    } else if (c === '(') {
      st.push(c);
    } else if (c === ')') {
      while (st.length > 0 && st[st.length - 1] !== '(') {
        post += st.pop();
      }
      st.pop();
    } else {
      if (c === '^') {
        while (st.length > 0 && prec(c) <= prec(st[st.length - 1])) {
          post += st.pop();
        }
      } else {
        while (st.length > 0 && prec(c) < prec(st[st.length - 1])) {
          post += st.pop();
        }
      }
      st.push(c);
    }
  }
  while (st.length > 0) post += st.pop();
  return post.split("").reverse().join("");
}
// USER_SOLUTION_END

