    public static String infixToPrefix(String s) {
        StringBuilder rev = new StringBuilder();
        for (int i = s.length() - 1; i >= 0; i--) {
            char c = s.charAt(i);
            if (c == '(') rev.append(')');
            else if (c == ')') rev.append('(');
            else rev.append(c);
        }
        Stack<Character> st = new Stack<>();
        StringBuilder post = new StringBuilder();
