vector<string> topKFrequentStrings(const vector<string>& words, int k) {
    unordered_map<string, int> count;
    for (const string& w : words) count[w]++;
    vector<string> unique;
    for (auto& pair : count) unique.push_back(pair.first);
    sort(unique.begin(), unique.end(), [&](const string& a, const string& b) {
        if (count[a] != count[b]) return count[a] > count[b];
        return a < b;
    });
