  }
  const visited = new Array(V).fill(false);
  const pq = new MinHeap();
  pq.push([0, 0]);
  let totalWeight = 0;
  while (!pq.isEmpty()) {
    const [w, u] = pq.pop();
    if (visited[u]) continue;
    visited[u] = true;
    totalWeight += w;
    for (const [v, weight] of adj[u]) {
      if (!visited[v]) {
        pq.push([weight, v]);
      }
    }
  }
  return totalWeight;
}
