int kosaraju(int V, const vector<vector<int>>& adj) {
    vector<bool> visited(V, false);
    vector<int> order;
    for (int i = 0; i < V; i++) {
        if (!visited[i]) dfs1(i, adj, visited, order);
    }
    vector<vector<int>> revAdj(V);
    for (int u = 0; u < V; u++) {
        for (int v : adj[u]) {
            revAdj[v].push_back(u);
        }
    }
    fill(visited.begin(), visited.end(), false);
    int sccCount = 0;
    for (int i = V - 1; i >= 0; i--) {
        int u = order[i];
        if (!visited[u]) {
            sccCount++;
            dfs2(u, revAdj, visited);
        }
    }
    return sccCount;
}
