    for (int i = 0; i < n; i++) parent[i] = i;
    int maxLen = 1;
    int lastIdx = 0;
    for (int i = 0; i < n; i++) {
        for (int prev = 0; prev < i; prev++) {
            if (nums[i] % nums[prev] == 0 && 1 + dp[prev] > dp[i]) {
                dp[i] = 1 + dp[prev];
                parent[i] = prev;
            }
        }
        if (dp[i] > maxLen) {
            maxLen = dp[i];
            lastIdx = i;
        }
    }
    vector<int> res;
    int curr = lastIdx;
    while (parent[curr] != curr) {
        res.push_back(nums[curr]);
        curr = parent[curr];
